/* ==UserStyle==
@name         Haimiya Roblox Theme
@namespace    Haimiya
@version      1.0.0
@description  Anime glass theme for Roblox
@author       You
==/UserStyle== */
@-moz-document domain("roblox.com") {
:root{
    --bg: url("https://files.catbox.moe/lqmyfo.png");
    --glass: rgba(20,20,30,.45);
    --glass2: rgba(25,25,35,.65);
}

/* Wallpaper */
html,
body,
#rbx-body{
    background: var(--bg) center center / cover no-repeat fixed !important;
}

/* Dark overlay for readability */
body::before{
    content:"";
    position:fixed;
    inset:0;
    background:rgba(0,0,0,.30);
    z-index:-1;
}

/* Main containers */
.content,
.content-container,
.container-main,
.section,
.card,
.game-card-container,
.game-home-page,
.profile-container,
.profile-header,
.friends-carousel-container,
.avatar-card,
.chat-container,
.modal-content{
    background:var(--glass)!important;
    backdrop-filter:blur(18px)!important;
    -webkit-backdrop-filter:blur(18px)!important;
    border-radius:18px!important;
    border:none!important;
}

/* Navigation */
.rbx-navbar,
.navbar,
.nav,
.header{
    background:var(--glass2)!important;
    backdrop-filter:blur(20px)!important;
}

/* Search */
input,
textarea{
    background:rgba(255,255,255,.10)!important;
    color:white!important;
    border:none!important;
}

/* Buttons */
button,
.btn-primary,
.btn-secondary{
    border-radius:12px!important;
}

/* Hover effect */
.card:hover,
.game-card-container:hover{
    transform:translateY(-3px);
    transition:.2s ease;
}

/* Scrollbar */
::-webkit-scrollbar{
    width:10px;
}

::-webkit-scrollbar-thumb{
    background:rgba(255,255,255,.20);
    border-radius:20px;
}
}
